import { messageMetadata, type ChatMessage } from "../../timeline";
import { text } from "./eventModel";
import useTransientStatus from "./useTransientStatus";

function CopyReply({ content, onInspect }: { content: string; onInspect: () => void }) {
  const [status, setStatus] = useTransientStatus();
  const copy = async () => {
    onInspect();
    try { await navigator.clipboard.writeText(content); setStatus("已复制回复"); }
    catch { setStatus("无法复制，请手动选择回复。"); }
  };
  return <div className="message-actions"><button type="button" className="icon-button" aria-label="复制回复" title="复制回复" onClick={() => void copy()}><svg viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><rect x="7" y="7" width="10" height="10" rx="2" /><path d="M13 7V4a1 1 0 0 0-1-1H4a1 1 0 0 0-1 1v8a1 1 0 0 0 1 1h3" /></svg></button>{status && <span className="copy-feedback" role="status">{status}</span>}</div>;
}


export default function AssistantMessage({ message, native, onInspect }: { message: ChatMessage; native: boolean; onInspect: () => void }) {
  const meta = messageMetadata(message.metadata);
  return <article data-scroll-key={`message:${message.id}`} className="message from-agent">
    <div className="message-meta"><span className="message-avatar">F</span><strong>Router</strong>
      <span className="reply-model" title={[meta.provider_id, meta.model_id].filter(Boolean).join(" / ")}>{meta.source === "router_notice" ? "任务通知" : text(meta.model_id, "模型未记录")}</span>
      {meta.execution_mode === "mock" && <span>模拟</span>}{meta.execution_mode === "live" && <span>真实执行</span>}
      {meta.execution_mode !== "live" && meta.execution_mode !== "mock" && <span>来源未知</span>}
      <time dateTime={message.created_at}>{message.created_at ? new Date(message.created_at).toLocaleString() : ""}</time>
    </div>
    <div className="message-body"><Markdown content={message.content} native={native} onInspect={onInspect} /></div>
    <CopyReply content={message.content} onInspect={onInspect} />
  </article>;
}

import AnimatedDetails from "../AnimatedDetails";
import { Chevron } from "./conversation/Icons";

export interface TurnDiffFile {
  path: string;
  receiptId: string;
  scrollKey: string;
  added?: number;
  removed?: number;
}

export interface TurnDiffProps {
  files: TurnDiffFile[];
  groupKey: string;
  initialExpanded: boolean;
  onExpandedChange: (expanded: boolean) => void;
  onInspect: () => void;
  onOpenFile?: (path: string) => void;
  onOpenHistory?: (receiptId: string, path: string) => void;
}

/** A file summary is derived only from successful live receipts in this activity group. */
export default function TurnDiff({ files, groupKey, initialExpanded, onExpandedChange, onInspect, onOpenFile, onOpenHistory }: TurnDiffProps) {
  if (!files.length) return null;
  const row = (file: TurnDiffFile) => <button type="button" className="activity-file-row turn-diff-file" key={file.path} data-scroll-key={file.scrollKey} title={file.path} disabled={!onOpenFile}
    onClick={() => { onInspect(); onOpenFile?.(file.path); }}>
    <svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true"><path d="M4 2h5l3 3v9H4V2Zm5 0v3h3" /></svg>
    <span className="turn-diff-path">{file.path}</span>
    {typeof file.added === "number" && typeof file.removed === "number" && <span className="turn-diff-stats" title="此文件已加载回执的增删数"><span className="file-added">+{file.added.toLocaleString()}</span><span className="file-removed">−{file.removed.toLocaleString()}</span></span>}
    <span className="activity-file-action">预览</span>
  </button>;
  return <section className="turn-diff activity-group-files" aria-label="记录的文件变更">
    <p className="activity-group-files-label sr-only">本组记录的文件</p>
    <header className="turn-diff-header"><span className="turn-diff-title">已编辑 {files.length} 个文件</span>
      {onOpenHistory && <div className="turn-diff-actions"><button type="button" onClick={() => { onInspect(); onOpenHistory(files[0].receiptId, files[0].path); }}>查看变更</button></div>}
    </header>
    <div className="turn-diff-files">{files.slice(0, 3).map(row)}</div>
    {files.length > 3 && <AnimatedDetails className="activity-more-files turn-diff-more" scrollKey={`group-files:${groupKey}`} initialExpanded={initialExpanded}
      onExpandedChange={onExpandedChange} onInspect={onInspect} summary={<><span>再显示 {files.length - 3} 个文件</span><Chevron /></>}>
      <div className="activity-more-files-body">{files.slice(3).map(row)}</div>
    </AnimatedDetails>}
  </section>;
}

export interface TimelineReadingAnchor { key: string; offset: number; top: number }

/** Capture before replacing an independently polled activity snapshot. */
export function captureTimelineReading(element: HTMLDivElement | null, following: boolean): TimelineReadingAnchor | null {
  if (!element?.getClientRects().length || following) return null;
  const viewport = element.getBoundingClientRect();
  const candidates = Array.from(element.querySelectorAll<HTMLElement>("[data-scroll-key]"))
    .map((node) => ({ node, bounds: node.getBoundingClientRect() }))
    .filter(({ bounds }) => bounds.height > 0 && bounds.bottom > viewport.top && bounds.top < viewport.bottom);
  const preferred = candidates.filter(({ node }) => !/^group(?:-files)?:/.test(node.dataset.scrollKey || ""));
  const anchor = (preferred.length ? preferred : candidates).sort((left, right) => Math.abs(left.bounds.top - viewport.top) - Math.abs(right.bounds.top - viewport.top))[0];
  return anchor ? { key: anchor.node.dataset.scrollKey!, offset: anchor.bounds.top - viewport.top, top: element.scrollTop } : null;
}
